### 3. Server vs. Client Components

**Server Components (Default)**
- Fetch data from databases/APIs close to the source
- Keep secrets and API keys safe
- Reduce JavaScript sent to browser
- Use async functions

```tsx
// app/posts/page.tsx - Server Component by default
import { getPosts } from '@/lib/data'

export default async function Page() {
  const posts = await getPosts()
  return (
    <ul>
      {posts.map(post => <li key={post.id}>{post.title}</li>)}
    </ul>
  )
}
```

**Client Components** - Mark with `'use client'`
- Use state and event handlers
- Lifecycle effects (`useEffect`)
- Browser APIs (`localStorage`, `window`, etc.)
- Custom hooks

```tsx
// app/ui/counter.tsx
'use client'

import { useState } from 'react'

export default function Counter() {
  const [count, setCount] = useState(0)

  return (
    <div>
      <p>{count}</p>
      <button onClick={() => setCount(count + 1)}>Click</button>
    </div>
  )
}
```

**Composing Server & Client Components**
```tsx
// app/page.tsx - Server Component
import { LikeButton } from '@/app/ui/like-button'

export default async function Page() {
  const post = await getPost(id)

  return (
    <main>
      <h1>{post.title}</h1>
      {/* Pass data from Server to Client as props */}
      <LikeButton likes={post.likes} />
    </main>
  )
}

// app/ui/like-button.tsx - Client Component
'use client'

export default function LikeButton({ likes }: { likes: number }) {
  const [isLiked, setIsLiked] = useState(false)
  return <button onClick={() => setIsLiked(!isLiked)}>Like ({likes})</button>
}
```

**Context Providers** (must be Client Components)
```tsx
// app/theme-provider.tsx
'use client'

import { createContext } from 'react'

export const ThemeContext = createContext({})

export default function ThemeProvider({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <ThemeContext.Provider value="dark">
      {children}
    </ThemeContext.Provider>
  )
}

// app/layout.tsx - Use in Server Component
import ThemeProvider from './theme-provider'

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html>
      <body>
        <ThemeProvider>{children}</ThemeProvider>
      </body>
    </html>
  )
}
```

