**Request Deduplication & Caching**
```tsx
// fetch requests are automatically memoized in a single render pass
// Use cache options to control caching behavior:

// Default: Next.js statically pre-renders and caches
await fetch('https://api.example.com/posts')

// No caching - dynamic rendering
await fetch('https://api.example.com/posts', { cache: 'no-store' })

// Custom caching
await fetch('https://api.example.com/posts', { cache: 'force-cache' })

// For non-fetch data sources, use React.cache()
import { cache } from 'react'

export const getPost = cache(async (id: string) => {
  return await db.query.posts.findFirst({ where: eq(posts.id, id) })
})
```

**Streaming Data to Client Components**
```tsx
// app/blog/page.tsx - Server Component
import Posts from '@/app/ui/posts'
import { Suspense } from 'react'

export default function Page() {
  // Don't await - pass promise to Client Component
  const posts = getPosts()

  return (
    <Suspense fallback={<div>Loading...</div>}>
      <Posts posts={posts} />
    </Suspense>
  )
}

// app/ui/posts.tsx - Client Component
'use client'
import { use } from 'react'

export default function Posts({
  posts,
}: {
  posts: Promise<{ id: string; title: string }[]>
}) {
  const allPosts = use(posts)  // Unwrap promise

  return (
    <ul>
      {allPosts.map(post => <li key={post.id}>{post.title}</li>)}
    </ul>
  )
}
```

**Sequential vs. Parallel Data Fetching**
```tsx
// Sequential (blocks until first completes)
export default async function Page() {
  const artist = await getArtist(username)
  const albums = await getAlbums(artist.id)  // Waits for artist first
}

// Parallel (both start immediately)
export default async function Page() {
  const artistData = getArtist(username)
  const albumsData = getAlbums(username)

  const [artist, albums] = await Promise.all([artistData, albumsData])
}
```

**Streaming with Suspense**
```tsx
// app/blog/page.tsx
import { Suspense } from 'react'
import BlogList from '@/components/BlogList'
import BlogListSkeleton from '@/components/BlogListSkeleton'

export default function BlogPage() {
  return (
    <div>
      <header>
        <h1>Welcome to the Blog</h1>
      </header>
      <main>
        {/* Header renders immediately, BlogList streams in */}
        <Suspense fallback={<BlogListSkeleton />}>
          <BlogList />
        </Suspense>
      </main>
    </div>
  )
}

// Or use a loading.tsx file for entire page
// app/blog/loading.tsx
export default function Loading() {
  return <div>Loading...</div>
}
```

---

### 5. Metadata (Replaces next/head)

**Static Metadata**
```tsx
// app/blog/layout.tsx
import type { Metadata } from 'next'

export const metadata: Metadata = {
  title: 'My Blog',
  description: 'Welcome to my blog',
  keywords: ['blog', 'next.js'],
  openGraph: {
    title: 'My Blog',
    description: 'Welcome to my blog',
    url: 'https://example.com',
    type: 'website',
  },
}

export default function Layout({ children }: { children: React.ReactNode }) {
  return <>{children}</>
}
```

**Dynamic Metadata** (from data)
```tsx
// app/blog/[slug]/page.tsx
import type { Metadata, ResolvingMetadata } from 'next'

type Props = {
  params: Promise<{ slug: string }>
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>
}

export async function generateMetadata(
  { params, searchParams }: Props,
  parent: ResolvingMetadata
): Promise<Metadata> {
  const slug = (await params).slug
  const post = await fetch(`https://api.example.com/blog/${slug}`).then(r => r.json())

  return {
    title: post.title,
    description: post.description,
  }
}

export default async function Page({ params }: Props) {
  const { slug } = await params
  // render page
}
```

**Static OG Images**
```tsx
// Place opengraph-image.jpg in app root or any route folder
// Supported formats: jpg, jpeg, png, gif

// Or generate dynamic OG images:
// app/blog/[slug]/opengraph-image.tsx
import { ImageResponse } from 'next/og'

export const size = { width: 1200, height: 630 }
export const contentType = 'image/png'

export default async function Image({ params }: { params: { slug: string } }) {
  const post = await getPost(params.slug)

  return new ImageResponse(
    (
      <div
        style={{
          fontSize: 128,
          background: 'white',
          width: '100%',
          height: '100%',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
        }}
      >
        {post.title}
      </div>
    )
  )
}
```

---

### 6. Error Handling

**Error Boundaries** (Uncaught Exceptions)
```tsx
// app/dashboard/error.tsx
'use client'  // Must be Client Component

import { useEffect } from 'react'

export default function ErrorPage({
  error,
  reset,
}: {
  error: Error & { digest?: string }
  reset: () => void
}) {
  useEffect(() => {
    console.error(error)
  }, [error])

  return (
    <div>
      <h2>Something went wrong!</h2>
      <button onClick={() => reset()}>Try again</button>
    </div>
  )
}
```

**Global Error Boundary**
```tsx
// app/global-error.tsx - Catches root layout errors
'use client'

export default function GlobalError({
  error,
  reset,
}: {
  error: Error & { digest?: string }
  reset: () => void
}) {
  return (
    <html>
      <body>
        <h2>Something went wrong!</h2>
        <button onClick={() => reset()}>Try again</button>
      </body>
    </html>
  )
}
```

**Expected Errors**
```tsx
// In Server Components - check response and redirect if needed
export default async function Page() {
  const res = await fetch('https://...')

  if (!res.ok) {
    return 'There was an error.'
  }

  return '...'
}

// Not Found - call notFound() function
import { notFound } from 'next/navigation'

export default async function Page({ params }: { params: { slug: string } }) {
  const post = await getPost(params.slug)

  if (!post) {
    notFound()  // Renders not-found.tsx
  }

  return <div>{post.title}</div>
}

// app/blog/[slug]/not-found.tsx
export default function NotFound() {
  return <div>404 - Post not found</div>
}
```

**Handle Errors in Server Actions**
```tsx
// app/actions.ts
'use server'

export async function createPost(prevState: any, formData: FormData) {
  const title = formData.get('title')
  const res = await fetch('https://api.example.com/posts', {
    method: 'POST',
    body: JSON.stringify({ title }),
  })

  if (!res.ok) {
    return { message: 'Failed to create post' }
  }

  return { success: true }
}

// app/ui/form.tsx - Client Component
'use client'

import { useActionState } from 'react'
import { createPost } from '@/app/actions'

export function Form() {
  const [state, formAction, pending] = useActionState(createPost, { message: '' })

  return (
    <form action={formAction}>
      <input type="text" name="title" required />
      {state?.message && <p>{state.message}</p>}
      <button disabled={pending}>Create</button>
    </form>
  )
}
```

---

### 7. Route Handlers (API Routes)

**Basic Route Handler**
```tsx
// app/api/posts/route.ts - Replaces pages/api/posts.js
export async function GET(request: Request) {
  return Response.json({ message: 'Hello' })
}

export async function POST(request: Request) {
  const body = await request.json()
  return Response.json({ created: true }, { status: 201 })
}

// Supports: GET, POST, PUT, PATCH, DELETE, HEAD, OPTIONS
```

**Dynamic Route Handlers**
```tsx
// app/api/posts/[id]/route.ts
import { NextRequest } from 'next/server'

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params
  return Response.json({ id })
}
```

**Caching Route Handlers**
```tsx
// By default GET routes are not cached
// Opt into caching:
export const dynamic = 'force-static'

export async function GET() {
  const data = await fetch('https://api.example.com/data', {
    headers: { 'API-Key': process.env.DATA_API_KEY },
  })
  return Response.json(await data.json())
}

// Static generation with generateStaticParams
export async function generateStaticParams() {
  return [{ id: '1' }, { id: '2' }, { id: '3' }]
}
```

**Route Conflicts**
```
// CONFLICT - Cannot have both in same route:
app/page.tsx + app/route.ts  ❌

// VALID - Different segments:
app/page.tsx + app/api/route.ts  ✅
```

---

### 8. Static Generation with generateStaticParams

**Replaces getStaticPaths from Pages Router**

```tsx
// app/blog/[slug]/page.tsx
export async function generateStaticParams() {
  const posts = await fetch('https://api.example.com/posts').then(r => r.json())

  return posts.map(post => ({
    slug: post.slug,
  }))
}

// Multiple versions of this page will be statically generated
// - /blog/post-1
// - /blog/post-2
// etc.
export default async function Page({
  params,
}: {
  params: Promise<{ slug: string }>
}) {
  const { slug } = await params
  const post = await getPost(slug)
  return <div>{post.title}</div>
}
```

**Multiple Dynamic Segments**
```tsx
// app/products/[category]/[product]/page.tsx
export function generateStaticParams() {
  return [
    { category: 'a', product: '1' },
    { category: 'b', product: '2' },
    { category: 'c', product: '3' },
  ]
}

export default async function Page({
  params,
}: {
  params: Promise<{ category: string; product: string }>
}) {
  const { category, product } = await params
  return <div>{category}: {product}</div>
}
```

**Catch-all Routes**
```tsx
// app/docs/[...slug]/page.tsx
export function generateStaticParams() {
  return [
    { slug: ['a', '1'] },
    { slug: ['b', '2'] },
  ]
}

export default async function Page({
  params,
}: {
  params: Promise<{ slug: string[] }>
}) {
  const { slug } = await params
  return <div>{slug.join('/')}</div>
}
```

**Control Behavior for Ungenerated Paths**
```tsx
// Generate only top 10 posts at build time
export async function generateStaticParams() {
  const posts = await fetch('https://api.example.com/posts').then(r => r.json())
  return posts.slice(0, 10).map(post => ({ slug: post.slug }))
}

// All other posts return 404
export const dynamicParams = false

export default async function Page({
  params,
}: {
  params: Promise<{ slug: string }>
}) {
  // ...
}
```

**Generate at Runtime (ISR/On-Demand)**
```tsx
// Empty array = generate on first request
export async function generateStaticParams() {
  return []
}

// OR use dynamic = 'force-static' for ISR
export const dynamic = 'force-static'

export default async function Page({
  params,
}: {
  params: Promise<{ slug: string }>
}) {
  // ...
}
```

---

### 9. Migration Path: Pages → App Router

**Key Mapping:**

| Pages Router | App Router | Notes |
|---|---|---|
| `pages/_app.js` | `app/layout.tsx` | Root layout (single file) |
| `pages/_document.js` | `app/layout.tsx` | Merge with root layout |
| `pages/[slug].js` | `app/[slug]/page.tsx` | Dynamic routes still work |
| `pages/api/posts.js` | `app/api/posts/route.ts` | Route Handlers |
| `getStaticProps` | Async Server Component | Fetch directly in component |
| `getStaticPaths` | `generateStaticParams()` | Same purpose, simpler API |
| `getServerSideProps` | Async Server Component | Fetch directly in component |
| `next/head` | `generateMetadata()` or `metadata` export | Built-in SEO support |
| `pages/404.js` | `app/[...slug]/not-found.tsx` | Not found boundary |
| `pages/_error.js` | `app/error.tsx` | Error boundaries |

**Incremental Migration Strategy:**
1. Create `app/layout.tsx` (root layout)
2. Migrate pages one by one from `pages/` to `app/`
3. Move API routes to `app/api/route.ts`
4. Replace data fetching functions
5. Delete `pages/` directory when complete

---

### 10. Key Patterns & Best Practices

**Reduce Client-Side JavaScript**
```tsx
// app/layout.tsx - Server Component
import Search from './search'  // Client Component
import Logo from './logo'      // Server Component

export default function Layout({ children }: { children: React.ReactNode }) {
  return (
    <>
      <nav>
        <Logo />
        <Search />  {/* Only this becomes Client-Side JS */}
      </nav>
      <main>{children}</main>
    </>
  )
}
```

**Protect Secrets**
```tsx
// app/api/secret/route.ts - Server-only
// This code never reaches the client
export async function GET() {
  const apiKey = process.env.SECRET_API_KEY
  const data = await fetch('https://api.example.com', {
    headers: { Authorization: `Bearer ${apiKey}` },
  })
  return Response.json(await data.json())
}

// To prevent accidental import in Client Component:
import 'server-only'

export async function getData() {
  // If someone imports this in a Client Component, build will error
}
```

**Route Props Type Helpers**
```tsx
import type { PageProps, LayoutProps } from 'next'

export default async function Page(props: PageProps<'/blog/[slug]'>) {
  const { slug } = await props.params
  return <h1>{slug}</h1>
}

export default function Layout(props: LayoutProps<'/dashboard'>) {
  return <section>{props.children}</section>
}
```

---

This comprehensive summary covers all 8 points you requested. The App Router is now the standard for Next.js development, offering better performance, simpler data fetching, and excellent developer experience through Server Components.

